pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 extraAmount) public {
        // 1. restrict to admissible domain: amounts that won't cause arithmetic overflow in setup
        bound(amount, 0, type(uint128).max);
        bound(extraAmount, 0, type(uint128).max);

        // 2. set up scenario: fund owner, then have owner send Ether to the contract
        address owner = address(uint160(c.owner()));
        vm.deal(owner, amount + extraAmount);
        vm.prank(owner);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "setup: initial deposit failed");

        // record owner's balance before withdrawal
        uint256 ownerBalanceBefore = owner.balance;

        // record contract's balance before withdrawal
        uint256 contractBalanceBefore = address(c).balance;

        // owner calls withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // 3. assertion: owner's balance must increase by exactly the contract's balance before the call
        assertTrue(owner.balance == ownerBalanceBefore + contractBalanceBefore);
    }
}

