pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit1, uint256 deposit2) public {
        // Bound deposits to avoid overflow
        bound(deposit1, 1, 1e36);
        bound(deposit2, 1, 1e36);

        // Fund owner
        address owner = c.owner();
        vm.deal(owner, deposit1 + deposit2);

        // Make deposits from two different EOAs to simulate real usage
        vm.prank(address(0x1234));
        vm.deal(address(0x1234), deposit1);
        (bool s1, ) = address(c).call{value: deposit1}("");
        require(s1);

        vm.prank(address(0x5678));
        vm.deal(address(0x5678), deposit2);
        (bool s2, ) = address(c).call{value: deposit2}("");
        require(s2);

        // Record owner balance and contract balance before withdrawAll
        uint256 ownerBefore = owner.balance;
        uint256 contractBefore = address(c).balance;

        // Call withdrawAll as owner
        vm.prank(owner);
        c.withdrawAll();

        // Record after balances
        uint256 ownerAfter = owner.balance;
        uint256 contractAfter = address(c).balance;

        // Invariant: sum(owner balance diff, contract remaining) == initial contract balance
        assertTrue((ownerAfter - ownerBefore) + contractAfter == contractBefore);
    }
}

