pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedBalance, uint256 extraDeposit) public {
        // Bound the balance to a reasonable range to avoid overflow in funding and to keep the test practical
        seedBalance = bound(seedBalance, 1, 1000 ether);
        extraDeposit = bound(extraDeposit, 0, 1000 ether);

        // Fund the contract with the initial balance
        vm.deal(address(c), seedBalance);

        // Optionally deposit more via fallback to increase depositsCount and balance
        if (extraDeposit > 0) {
            vm.deal(address(this), extraDeposit);
            (bool ok,) = address(c).call{value: extraDeposit}("");
            require(ok, "extra deposit failed");
