        // Owner calls withdrawAll
        vm.prank(c.owner());
        (bool success,) = address(c).call(abi.encodeWithSelector(C.withdrawAll.selector));

        // Assert: after a successful withdrawAll, the contract's balance must be zero
        assertTrue(!success || address(c).balance == 0);
    }
}

