contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 amountToSend) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(c));
        vm.assume(amountToSend > 0);

        // Setup: Owner deposits some Ether into the contract.
        vm.deal(address(c), 10 ether);

        // Setup: Non-owner sends money via sendMoney, which requires onlyOwner in the correct version.
        // In the correct version, this call will revert because nonOwner is not the owner.
        // In the buggy version, this call will succeed.
        bool sendMoneySucceeded = false;
        vm.prank(nonOwner);
        try c.sendMoney(address(0xdead), amountToSend) {
            sendMoneySucceeded = true;
        } catch {
            sendMoneySucceeded = false;
        }

        // After the sendMoney attempt, the owner tries to withdrawAll.
        bool ownerCanWithdrawAll = false;
        vm.prank(address(this));
        try c.withdrawAll() {
            ownerCanWithdrawAll = true;
        } catch {
            ownerCanWithdrawAll = false;
        }

        // Invariant: If sendMoney reverted for the non-owner (correct behavior), the owner must be able to withdrawAll successfully.
        // If the bug allows a non-owner to call sendMoney, it may drain funds or alter state such that the owner's subsequent withdrawAll is affected.
        // In the correct version, sendMoney always reverts for a non-owner, so the owner's withdrawAll always succeeds.
        // In the buggy version, a non-owner can successfully send funds, reducing the balance, but the owner can still call withdrawAll (it just gets less).
        // However, because the bug also makes withdrawAll callable by anyone, a more precise invariant is needed.
        // The true invariant: The owner's ability to withdrawAll is independent of a non-owner's attempt to call sendMoney.
        // In the correct version, nonOwner calling sendMoney always reverts, so ownerCanWithdrawAll is true.
        // In the buggy version, nonOwner calling sendMoney succeeds but ownerCanWithdrawAll is still true (anyone can withdraw, even owner).
        // This does not cause a difference.

        // Better invariant targeting the difference in onlyOwner for withdraw:
        // In the correct version, only the owner can successfully call withdrawAll.
        // In the buggy version, anyone can successfully call withdrawAll.
        // Therefore, after any sequence, a non-owner attempting to withdrawAll should revert in the correct version but succeed in the buggy version.
        // We can assert that a nonOwner call to withdrawAll always reverts in the correct version.
        // But we must drive through sendMoney first, as specified.

        // Let's use the required entry point: sendMoney.
        // The difference stated: after a call to sendMoney completes, the value of state variable "withdraw" differs.
        // "withdraw" is a function, not a state variable. They might mean depositsCount?
        // Actually, the description says "the value of state variable `withdraw` differs: `P.withdraw() != M.withdraw()`".
        // There is no state variable withdraw. The only state variables are owner and depositsCount.
        // The difference must be in the behavior of the withdraw function (accessible to anyone in bug, only to owner in correct).
        // So a general rule: After sendMoney is called by anyone, a subsequent call to withdrawAll by a non-owner must revert.

        // That invariant holds for the correct version: sendMoney is onlyOwner, so if a non-owner calls it, it reverts.
        // But wait, if sendMoney reverts for a non-owner, we never reach a state where a non-owner's sendMoney completed.
        // The invariant must hold for ALL inputs, including those where sendMoney succeeds (only owner calls it).
        // Even if the owner calls sendMoney, a non-owner calling withdrawAll should revert.
        // So let's test: regardless of who calls sendMoney (owner or not), a non-owner calling withdrawAll should always revert.
        // In the correct version, this is true. In the buggy version, it is false (anyone can withdrawAll).

        // But we must also ensure we don't exclude the bug-triggering input. The bug is triggered when a non-owner calls withdrawAll.
        // So we assert that a non-owner calling withdrawAll always reverts.

        vm.prank(nonOwner);
        try c.withdrawAll() {
            assertTrue(false, "Non-owner should not be able to withdrawAll in correct version");
        } catch {
            // Expected in correct version
        }

        // Additionally, we can assert something about balance or depositsCount, but the above suffices.
        // However, the test must PASS on reference for ALL inputs and FAIL on buggy for SOME.
        // In the buggy version, nonOwner calling withdrawAll will succeed, so the assertTrue(false) will be reached, causing test failure.
        // This satisfies the requirement.
    }
