        // Trigger sendMoney with the given amount, which will call back into receive
        target.sendMoney(address(this), amount);
        locked = false;
    }

    receive() external payable {
        if (!locked) {
            // Re-entrant withdraw: this should revert the whole transaction
            target.withdraw(msg.value);
            // Force a revert so the reference's transfer fails and reverts everything
            revert("forced revert to test balance change");
        }
    }
}

