pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, address _target) public {
        vm.assume(_value > 0 && _value <= address(this).balance / 2);
        vm.assume(_target != address(c) && _target != address(0));
        vm.assume(_target != address(this) && _target != address(vm));
        // deploy adversarial callee that rejects Ether
        FailingReceiver failer = new FailingReceiver();
        address adversarialTarget = address(failer);
        // fund c
        vm.deal(address(c), _value * 2);
        uint256 balanceBefore = address(c).balance;
        // call sendMoney
        c.sendMoney(adversarialTarget, _value);
        uint256 balanceAfter = address(c).balance;
        // Reference: sendMoney with call returns false on failure, balance unchanged
        // Bug: transfer reverts on failure, which can cause a revert and leave balance unchanged
        // The invariant: after a non-reverting sendMoney, balance decreases by _value
        // We check: if the call did not revert, balance decreased properly
        // For the reference, call returns false, no revert, balance unchanged -> no assertion violation
        // For the bug, transfer reverts, so the call reverts, and our test reverts before assertion
        // We need to catch this: use try/catch and assert that the outcome is consistent
        bool ok;
        try c.sendMoney(adversarialTarget, _value) { ok = true; } catch { ok = false; }
        // For the reference: call fails, returns false, no revert -> ok == true
        // For the bug: transfer fails, revert -> ok == false
        if (ok) {
            uint256 balanceAfterSuccess = address(c).balance;
            assertEq(balanceAfterSuccess, balanceBefore - _value);
        } else {
            // Revert: balance unchanged
            assertEq(address(c).balance, balanceBefore);
        }
    }
}

