        vm.assume(target != address(c));
        vm.assume(target != address(0));

        // Fund the contract so it has ether to send. Use a random funder distinct from the owner.
        address funder = makeAddr("funder");
        vm.deal(funder, initialFunding);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: initialFunding}("");
        require(sent, "funding failed");

        // Record balance before the call
        uint256 balanceBefore = address(c).balance;

        // The actor is NOT the owner; use a random non-owner address.
        address actor = makeAddr("nonOwner");
        vm.assume(actor != c.owner());
        vm.assume(actor != funder);

        // In the reference contract, a non-owner calling sendMoney should revert (onlyOwner).
        // In the mutant, it succeeds and transfers ether.
        // We wrap the call in try-catch to detect revert.
        vm.prank(actor);
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference (correct) contract: ok == false, balanceBefore == address(c).balance.
        // For the mutant: ok == true, balanceBefore - amount == address(c).balance.
        // The general invariant: If the call succeeds, the contract's balance must decrease by exactly the amount sent.
        // This holds for the reference (since it never succeeds for non-owner) and fails for the mutant (it succeeds without decreasing balance? No: the mutant actually transfers, so balance decreases.
        // Wait: the mutant modifier lets non-owners call sendMoney and the call succeeds, sending ether, so balance DOES decrease.
        // We need a property that PASSES for reference and FAILS for mutant.
        // Reference: non-owner call reverts, balance unchanged.
        // Mutant: non-owner call succeeds, balance changes.
        // A property that holds for reference: (ok == false) || (address(c).balance == balanceBefore - amount)
        // For reference, ok==false always, property true.
        // For mutant, ok==true and address(c).balance == balanceBefore - amount, property true. That would pass for both!
        // We need one that fails for mutant. Let's think: the bug lets ANYONE withdraw via sendMoney, while the reference only owner can.
        // The invariant we can check: After a call by a non-owner, the contract's balance MUST remain unchanged.
        // For reference, true. For mutant, false because the call succeeds and balance drops.
        // So: assertEq(address(c).balance, balanceBefore, "non-owner should not be able to move funds");
        // But that's not a general rule about sendMoney's internal logic; it's a security property.
        // The prompt says: "after a call to sendMoney(...) completes, the value of state variable sendMoney differs" — but sendMoney is a function, not a state variable. Probably a typo; they mean something else?
        // The instruction: "Driven through the public/external entry sendMoney, P and M differ in this way: after a call to sendMoney(...) completes, the value of state variable sendMoney differs: P.sendMoney() != M.sendMoney()." That is nonsensical.
        // We'll infer: after sendMoney, some observable state differs. Since onlyOwner is removed, non-owners can call it. The correct contract prevents non-owners from calling, so balance doesn't change. The mutant allows it, so balance changes. So the invariant: non-owner's call to sendMoney does not alter the contract's balance.
        // This is a universal property about the contract's behavior under non-owner interaction.
        assertEq(address(c).balance, balanceBefore, "non-owner should not change balance via sendMoney");
    }
}

